}

local signTextOverlay = GlobalEvent("SignTextOverlay")

function signTextOverlay.onStartup()
	local applied, kept, missing = 0, 0, 0
	for _, entry in ipairs(signTexts) do
		local tile = Tile(entry.pos)
		local item = tile and tile:getItemById(entry.id)
		if not item then
			missing = missing + 1
			logger.warn("[SignTextOverlay] item {} not found at {}", entry.id, entry.pos:toString())
		else
			local current = item:getAttribute(ITEM_ATTRIBUTE_TEXT)
			if current and current ~= "" then
				kept = kept + 1
			else
				item:setText(entry.text)
				applied = applied + 1
			end
		end
	end
	logger.info("[SignTextOverlay] {} sign texts applied, {} kept from map, {} not found", applied, kept, missing)
	return true
end

signTextOverlay:register()
